        def moved():
            sha = self.push_to("lane2")
            self.host.prs = [("lane1", tips["lane1"], "main"), ("lane2", sha, "lane1"), ("lane3", tips["lane3"], "lane2")]
        self.host.on_merged = moved
        rc, out = self.go()
        self.assertEqual(rc, 0, out)
        kept_line(self, out, "lane1")
